#include <deque>
#include <iostream>

int main() {
    std::deque<int> d = {3, 4, 5};

    // O(1) insertion at the front
    d.push_front(2);
    d.push_front(1);

    // O(1) insertion at the back
    d.push_back(6);

    // Random access is supported
    std::cout << "Element at index 3: " << d[3] << std::endl; // Output: 4

    // Output: 1 2 3 4 5 6 
    for (int x : d) {
        std::cout << x << " ";
    }
}
